import { browserSigner, embeddedSignerInit } from './embedded-signer';
export let embedded = null;
export async function generateSignature(url) {
    try {
        const sig = await browserSigner(url);
        if (sig) {
            console.log('✅ Firma desde navegador real');
            return sig;
        }
        console.warn('⚠️ navegador no rindió firma, usando embebido');
    }
    catch (e) {
        console.error('❌ Error navegador:', e);
    }
    try {
        if (!embedded) {
            embedded = await embeddedSignerInit();
        }
        const sig = await embedded.sign(url);
        console.log('✅ Firma desde embedded signer');
        return sig;
    }
    catch (e) {
        throw new Error(`Fallback error: ${e.message}`);
    }
}
export async function cleanupSigner() {
    if (embedded) {
        await embedded.close();
        embedded = null;
    }
}
